<script setup lang="ts">
import {ref,onMounted,toRaw} from 'vue'
import {api,t,lang,type Organization,type List} from '../api'
interface Account {id:number;organization_id:number;login:string;active:boolean;must_change:boolean;organization_name:Record<string,string>;organization_active:boolean}
const users=ref<Account[]>([]),total=ref(0),page=ref(1),q=ref(''),busy=ref(false),error=ref(''),notice=ref(''),editing=ref<Account>(),creating=ref(false),login=ref(''),organizationId=ref(0),orgQuery=ref(''),organizations=ref<Organization[]>([]),orgPage=ref(1),orgTotal=ref(0),credentials=ref<{login:string;temporary_password:string}>()
async function run(action:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await action()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function load(){const data=await api<List<Account>>(`/admin/users?page=${page.value}&q=${encodeURIComponent(q.value)}`);users.value=data.items;total.value=data.total}
async function loadOrgs(){const data=await api<List<Organization>>(`/admin/organizations?page=${orgPage.value}&q=${encodeURIComponent(orgQuery.value)}`);organizations.value=data.items;orgTotal.value=data.total}
async function create(){credentials.value=await api('/admin/users',{method:'POST',body:JSON.stringify({login:login.value,organization_id:organizationId.value})});creating.value=false;login.value='';await load()}
function startEdit(account:Account){editing.value=structuredClone(toRaw(account));creating.value=false;credentials.value=undefined}
async function save(){await api('/admin/users/'+editing.value!.id,{method:'PUT',body:JSON.stringify({login:editing.value!.login,active:editing.value!.active})});editing.value=undefined;await load();notice.value=t('Сақталды. Ескі сессиялар жабылды.','Сохранено. Старые сессии закрыты.')}
async function reset(account:Account){if(!window.confirm(t(account.login+' құпиясөзін қалпына келтіру керек пе?', 'Сбросить пароль '+account.login+'? Его текущие сессии будут закрыты.')))return;credentials.value=undefined;credentials.value=await api('/admin/users/'+account.id+'/reset-password',{method:'POST'});await load()}
onMounted(()=>run(load))
</script>
<template><section><div class="section-heading"><div><p class="eyebrow">{{t('ТІРКЕЛГІЛЕР ЖӘНЕ ҚОЛЖЕТІМДІЛІК','УЧЁТНЫЕ ЗАПИСИ И ДОСТУП')}}</p><h1>{{t('Пайдаланушылар','Пользователи')}}</h1></div><button class="primary-button" :disabled="busy" @click="run(async()=>{creating=true;editing=undefined;credentials=undefined;organizationId=0;orgPage=1;orgQuery='';await loadOrgs()})">+ {{t('Қызметкер қосу','Добавить сотрудника')}}</button></div><p v-if="error" class="notice" role="alert">{{error}}</p><p v-if="notice" class="success" role="status">{{notice}}</p><div v-if="credentials" class="success" role="status"><div class="section-heading"><strong>{{t('Уақытша құпиясөз','Временный пароль')}} · {{credentials.login}}</strong><button @click="credentials=undefined">{{t('Жабу','Закрыть')}}</button></div><code>{{credentials.temporary_password}}</code><p>{{t('Бір рет көрсетіледі. Алғашқы кіру кезінде қызметкер оны өзгертеді.','Показывается один раз. При первом входе сотрудник сменит его.')}}</p></div>
<div v-if="creating" class="editor-card"><div class="section-heading"><h2>{{t('Жаңа қызметкер','Новый сотрудник')}}</h2><button @click="creating=false">{{t('Жабу','Закрыть')}}</button></div><form class="filters" @submit.prevent="run(async()=>{orgPage=1;await loadOrgs()})"><label>{{t('Ұйымды іздеу','Поиск организации')}}<input v-model="orgQuery"></label><button :disabled="busy">{{t('Іздеу','Найти')}}</button></form><div v-if="orgTotal>20" class="pagination"><button :disabled="busy||orgPage===1" @click="run(async()=>{orgPage--;await loadOrgs()})">←</button><span>{{orgPage}} / {{Math.ceil(orgTotal/20)}}</span><button :disabled="busy||orgPage*20>=orgTotal" @click="run(async()=>{orgPage++;await loadOrgs()})">→</button></div><form @submit.prevent="run(create)"><div class="form-grid"><label>{{t('Ұйым','Организация')}}<select v-model="organizationId" required><option :value="0" disabled>{{t('Таңдаңыз','Выберите')}}</option><option v-for="org in organizations.filter(o=>o.active)" :key="org.id" :value="org.id">{{org.name[lang]||org.slug}}</option></select></label><label>{{t('Логин','Логин')}}<input v-model="login" minlength="3" maxlength="100" autocomplete="off" required></label></div><button class="primary-button" :disabled="busy||!organizationId">{{t('Тіркелгі жасау','Создать учётную запись')}}</button></form></div>
<form v-if="editing" class="editor-card" @submit.prevent="run(save)"><div class="section-heading"><h2>{{t('Тіркелгіні өзгерту','Редактирование учётной записи')}}</h2><button type="button" @click="editing=undefined">{{t('Жабу','Закрыть')}}</button></div><label>{{t('Логин','Логин')}}<input v-model="editing.login" minlength="3" maxlength="100" required></label><label class="check"><input type="checkbox" v-model="editing.active">{{t('Кіруге рұқсат беру','Разрешить вход')}}</label><button class="primary-button" :disabled="busy">{{t('Сақтау','Сохранить')}}</button></form>
<form class="filters" @submit.prevent="run(async()=>{page=1;await load()})"><label>{{t('Логин немесе ұйым','Логин или организация')}}<input v-model="q" :placeholder="t('Пайдаланушыны табу','Найти пользователя')"></label><button :disabled="busy">{{t('Іздеу','Найти')}}</button></form><div class="table-scroll"><table><thead><tr><th>{{t('Логин','Логин')}}</th><th>{{t('Ұйым / рөл','Организация / роль')}}</th><th>{{t('Күйі','Статус')}}</th><th>{{t('Әрекеттер','Действия')}}</th></tr></thead><tbody><tr v-for="account in users" :key="account.id"><td><strong>{{account.login}}</strong><small v-if="account.must_change" class="quiet account-note">{{t('Құпиясөзді өзгерту қажет','Требуется смена пароля')}}</small></td><td>{{account.organization_id?(account.organization_name[lang]||account.organization_name.ru):t('Орталық әкімші','Центральный администратор')}}</td><td><span class="tag" :class="{'tag-muted':!account.active||!account.organization_active}">{{!account.active?t('Бұғатталған','Заблокирован'):!account.organization_active?t('Ұйым өшірілген','Организация отключена'):t('Белсенді','Активен')}}</span></td><td><div v-if="account.organization_id" class="row-actions"><button :disabled="busy" @click="startEdit(account)">{{t('Өзгерту','Редактировать')}}</button><button :disabled="busy" @click="run(()=>reset(account))">{{t('Құпиясөзді қалпына келтіру','Сбросить пароль')}}</button></div><span v-else class="quiet">{{t('Қорғалған тіркелгі','Защищённая учётная запись')}}</span></td></tr></tbody></table></div><p v-if="!users.length" class="empty">{{busy?t('Жүктелуде…','Загрузка…'):t('Пайдаланушылар табылмады','Пользователи не найдены')}}</p><div v-if="total>20" class="pagination"><button :disabled="page===1||busy" @click="run(async()=>{page--;await load()})">←</button><span>{{page}} / {{Math.ceil(total/20)}}</span><button :disabled="page*20>=total||busy" @click="run(async()=>{page++;await load()})">→</button></div></section></template>
